/**
 * SoloLevelingTheme — animated wallpaper (video).
 *
 * WHY A VIDEO AND NOT AN ANIMATED IMAGE (2026-07-30): an animated GIF/WebP
 * used as a full-screen CSS background makes the browser decode a frame and
 * REPAINT THE WHOLE VIEWPORT on every frame, on the main thread, forever —
 * that is why the earlier animated wallpaper had to be reverted to a static
 * image. A muted looping <video> is decoded by the media pipeline and
 * composited on the GPU, so the renderer thread stays essentially idle.
 *
 * Source: the original 49MB SLEndingBest.gif (recovered from git b3befbd),
 * re-encoded H.264 1100x1100 @ 15fps (its native rate) CRF 26 = 770KB.
 * Embedded as a data URI because this branch is never pushed to a remote,
 * so a raw.githubusercontent URL would not resolve.
 *
 * OFF by default. Toggle in SoloLevelingTheme settings; honours
 * prefers-reduced-motion and pauses while the window is hidden.
 */

const WALLPAPER_VIDEO_ID = "sl-wallpaper-video";
const WALLPAPER_VIDEO_STYLE_ID = "sl-wallpaper-video-style";
const WALLPAPER_VIDEO_DATA_URL = "data:video/mp4;base64,";

function mountWallpaperVideo() {
  if (document.getElementById(WALLPAPER_VIDEO_ID)) return;
  try {
    if (window.matchMedia?.("(prefers-reduced-motion: reduce)")?.matches) return;
  } catch (_) {}

  const video = document.createElement("video");
  video.id = WALLPAPER_VIDEO_ID;
  video.src = WALLPAPER_VIDEO_DATA_URL;
  video.muted = true;
  video.defaultMuted = true;
  video.loop = true;
  video.autoplay = true;
  video.playsInline = true;
  video.setAttribute("aria-hidden", "true");
  // z-index -2 = the wallpaper layer itself. The FIRST attempt used -3, which
  // put the video BEHIND body::before — a fully opaque (opacity 1.0),
  // cover-sized static image — so it was perfectly hidden and the background
  // looked unchanged. The static layer is now suppressed while the video is
  // mounted; body::after (overlay, -1) still composites on top as before.
  video.style.cssText =
    "position:fixed;inset:0;width:100%;height:100%;object-fit:cover;" +
    "z-index:-2;pointer-events:none;opacity:var(--sl-bg-opacity,1);";

  if (!document.getElementById(WALLPAPER_VIDEO_STYLE_ID)) {
    const style = document.createElement("style");
    style.id = WALLPAPER_VIDEO_STYLE_ID;
    style.textContent =
      'body[data-sl-video-wallpaper="true"]::before{background-image:none !important;}';
    (document.head || document.documentElement).appendChild(style);
  }
  document.body?.setAttribute("data-sl-video-wallpaper", "true");

  // Surface load/decode failures instead of silently showing nothing.
  video.addEventListener("error", () => {
    console.error("[SoloLevelingTheme] wallpaper video failed to load:", video.error?.code, video.error?.message);
    document.body?.removeAttribute("data-sl-video-wallpaper");
  });

  (document.body || document.documentElement).appendChild(video);
  video.play?.().catch((err) => {
    console.error("[SoloLevelingTheme] wallpaper video play() rejected:", err?.name, err?.message);
  });

  // SELF-REPORT (2026-07-30): a paused video's first frame is visually
  // identical to the static wallpaper (same artwork), so "is it playing?"
  // cannot be answered by looking. Log hard state once, 3s after mount, into
  // the BD debug log where it can be read without DevTools.
  setTimeout(() => {
    try {
      const t1 = video.currentTime;
      setTimeout(() => {
        const cs = getComputedStyle(video);
        console.log("[SoloLevelingTheme] WALLPAPER VIDEO STATE", {
          connected: video.isConnected,
          paused: video.paused,
          advancing: video.currentTime > t1,
          currentTime: +video.currentTime.toFixed(2),
          readyState: video.readyState,      // 4 = HAVE_ENOUGH_DATA
          networkState: video.networkState,  // 3 = NO_SOURCE (blocked/failed)
          errorCode: video.error?.code ?? null,
          videoWidth: video.videoWidth,
          zIndex: cs.zIndex,
          opacity: cs.opacity,
          display: cs.display,
          visibility: cs.visibility,
          bodyAttr: document.body?.getAttribute("data-sl-video-wallpaper"),
        });
      }, 1000);
    } catch (_) {}
  }, 3000);

  // Pause while hidden: a backgrounded window should not be decoding video.
  const onVis = () => {
    if (document.hidden) video.pause();
    else video.play?.().catch(() => {});
  };
  document.addEventListener("visibilitychange", onVis);
  video._slOnVis = onVis;
}

function unmountWallpaperVideo() {
  // Restore the static wallpaper layer first, so there is never a frame with
  // no background at all.
  document.body?.removeAttribute("data-sl-video-wallpaper");
  document.getElementById(WALLPAPER_VIDEO_STYLE_ID)?.remove();

  const video = document.getElementById(WALLPAPER_VIDEO_ID);
  if (!video) return;
  try {
    if (video._slOnVis) document.removeEventListener("visibilitychange", video._slOnVis);
    video.pause();
    video.removeAttribute("src");
    video.load?.();
  } catch (_) {}
  video.remove();
}

module.exports = { mountWallpaperVideo, unmountWallpaperVideo, WALLPAPER_VIDEO_ID };
